.button {
  border: 2px solid transparent;
  border-radius: 0.5rem;
  padding: 0.7rem 1rem;
  background: #1d4ed8;
  color: #fff;
}

.button:hover {
  filter: brightness(0.92);
}

.button:focus-visible {
  outline: 3px solid #1e40af;
  outline-offset: 3px;
}

.button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}
